# ── Juz' 2 (Mushaf pages 22-41) ────────────────────────────────────────────────
KHD = 'خلاد'
FIVE_QIYAS = 'إبدال الهمزة ألفًا مع القصر والتوسط والإشباع، وتسهيلها مع الروم إشباعًا وقصرًا؛ ويوافقه هشام عدا وجه التسهيل مع الإشباع فله فيه التوسط.'

def imalah3(alt=True):
    """أمالها حمزة والكسائي وخلف العاشر، وقلّلها ورش (بخلف عنه)."""
    return [('حمزة', 'إمالة'), ('الكسائي', 'إمالة'), (K10, 'إمالة'), (W, 'تقليل')]

def imalah4():
    """… ومعهم أبو عمرو."""
    return [('أبو عمرو', 'إمالة'), ('حمزة', 'إمالة'), ('الكسائي', 'إمالة'), (K10, 'إمالة'), (W, 'تقليل')]

def imalah_nar():
    """﴿ٱلنَّارِ﴾ وبابه: أمالها أبو عمرو والدوري عن الكسائي، وقلّلها ورش."""
    return [('أبو عمرو', 'إمالة'), ('DURI_KISAI', 'إمالة'), (W, 'تقليل')]

def kisai_waqf():
    return [('الكسائي', 'إمالة')]

def duri_amr():
    return [('DURI_AMR', 'إمالة')]

# «لخلف ثلاثة أوجه ولخلّاد وجهان» — the recurring وقف حمزة shape at a hamzat-qat' after sukun.
def khalaf_khallad():
    return [(KH, 'السكت أو النقل أو التحقيق'), (KHD, 'النقل أو التحقيق')]

