    """ذوات الياء التي أمالها حمزة والكسائي وخلف العاشر وقللها ورش وأبو عمرو."""
    return [('حمزة', 'إمالة'), ('الكسائي', 'إمالة'), (K10, 'إمالة'),
            (W, 'تقليل'), ('أبو عمرو', 'تقليل')]

